	void put(const endian_func& adaptor) {
		const auto swapped = adaptor.to();
		write(&swapped, sizeof(swapped));
	}

	/**
	 * @brief Writes bytes from the provided buffer to the stream.
	 * 
	 * @tparam T POD type.
