void reserve(const size_type length) override {
		size_type remaining = length;
		intrusive_node* tail = root_.prev;

		do {
			storage_type* buffer;

			if(tail == &root_) [[unlikely]] {
				buffer = allocate();
				link_tail_node(&buffer->node);
