void copy(void* destination, size_type length) const {
		assert(!region_overlap(buffer_.data(), buffer_.size(), destination, length));

		if(length > size()) {
			HEXI_THROW(buffer_underrun(length, read_, size()));
		}

		std::memcpy(destination, read_ptr(), length);
	}

